private void validarModalidadeEntrega(ModalidadeEntrega modalidade, BigDecimal pesoTotal) {
    if (!modalidade.aceitaPeso(pesoTotal)) {
        throw new CheckoutException("MODALIDADE_INDISPONIVEL");
